<?php use CmuLms\View; $title='Item analysis'; include __DIR__.'/../layout/header.php'; ?><section class="hero"><span><?=View::e($exam['code'])?> · Assessment analysis</span><h1><?=View::e($exam['title'])?></h1><p>Correct-response rates are based on submitted attempts.</p></section><section class="card"><table><tr><th>#</th><th>Question</th><th>Answered</th><th>Correct</th><th>Correct rate</th></tr><?php $n=1;foreach($items as $item):$rate=$item['answered']?round($item['correct']/$item['answered']*100,1):0;?><tr><td><?=$n++?></td><td><?=View::e($item['prompt'])?></td><td><?=View::e($item['answered'])?></td><td><?=View::e($item['correct'])?></td><td><?=View::e($rate)?>%</td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5">No submitted answers are available.</td></tr><?php endif;?></table></section><?php include __DIR__.'/../layout/footer.php'; ?>
